{
  "name": "aurora-inbox",
  "displayName": "Aurora Inbox",
  "version": "1.0.1",
  "description": "Manage contacts, chats, channels, chatbots, opportunities, and webhooks in Aurora Inbox — AI-powered team inbox for WhatsApp, Facebook, and more.",
  "author": {
    "name": "Aurora Inbox, S.A.P.I. de C.V.",
    "url": "https://www.aurorainbox.com"
  },
  "license": "MIT",
  "homepage": "https://www.aurorainbox.com",
  "repository": "https://github.com/aurorainbox/aurora-mcp-plugin",
  "keywords": ["whatsapp", "messaging", "crm", "chatbot", "inbox"],
  "mcpServers": {
    "aurora-inbox": {
      "command": "npx",
      "args": ["-y", "@aurora-inbox/mcp-server"],
      "env": {
        "AURORA_API_URL": "${AURORA_API_URL}",
        "AURORA_API_KEY": "${AURORA_API_KEY}"
      }
    }
  }
}
